SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "令狐涣韩偓因参与返正任翰林学士。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p025·原文件第64行", "note": "原文：中书舍人令狐涣、给事中韩偓皆预其谋，故擢为翰林学士，数召对，访以机密。；核对说明：按原文动作分录，不外推结果。", "status": "draft", "id": "f75226b1-6365-54a3-8d32-177bb5e3d27f", "subject_id": "319f11e9-8c9b-5d2d-b53e-6a2cab111dd3", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "901年返正后；确日未载", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p025·原文件第64行", "note": "原文：中书舍人令狐涣、给事中韩偓皆预其谋，故擢为翰林学士，数召对，访以机密。；核对说明：沿主书段落次序；干支日未换算公历日。", "status": "draft", "id": "c93977c4-83d5-5bea-b6f9-44d8a6c618ca", "subject_id": "319f11e9-8c9b-5d2d-b53e-6a2cab111dd3", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记令狐涣：参与返正并受擢者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p025·原文件第64行", "note": "原文：上之返正也，中书舍人令狐涣、给事中韩偓皆预其谋，故擢为翰林学士，数召对，访以机密。涣，綯之子也。时上悉以军国事委崔胤，每奏事，上与之从容，或至然烛。宦官畏之侧目，事无大小，皆咨胤而后行。胤志欲尽除之，韩偓屡谏曰：“事禁太甚。此辈亦不可全无，恐其党迫切，更生他变。”胤不从。丁卯，上独召偓，问曰：“敕使中为恶者如林，何以处之？”对曰：“东内之难，敕使谁非同恶，处之当在正旦，今已失其时矣。”上曰：“当是时，卿何不为崔胤言之？”对曰：“臣见陛下诏书云，‘自刘季述等四家之外，其馀一无所问。’夫人主所重，莫大于信，既下此诏，则守之宜坚。若复戮一人，则人人惧死矣。然后来所去者已为不少，此其所以忷忷不安也。陛下不若择其尤无良者数人，明示其罪，置之于法，然后抚谕其余曰：‘吾恐尔曹谓吾心有所贮，自今可无疑矣。’乃择其忠厚者使为之长。其徒有善则奖之，有罪则惩之，咸自安矣。今此曹在公私者以万数，岂可尽诛邪！夫帝王之道，当以重厚镇之，公正御之，至于琐细机巧，此机生则彼机应矣，终不能成大功，所谓理丝而棼之者也。况今朝廷之权，散在四方。苟能先收此权，则事无不可为者矣。?鄙仙钜晕滑曰：“此事终以属卿。”；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "f3a691d4-8d63-54f2-951b-cf8d62763877", "subject_id": "33d2d2f1-0c60-5472-ba58-5d8d25df62fc", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "令狐涣：参与返正并受擢者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p025·原文件第64行", "note": "原文：中书舍人令狐涣、给事中韩偓皆预其谋，故擢为翰林学士，数召对，访以机密。；核对说明：参