aft", "id": "2b5251f3-4aa4-520f-8cd6-a7e75d755103", "subject_id": "b215a648-250b-5e30-aa5a-052cd67b46eb", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记韩全诲：求哀者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p029·原文件第68行", "note": "原文：崔胤请上尽诛宦官，但以宫人掌内诸司事。宦官属耳，颇闻之，韩全诲等涕泣求哀于上，上乃令胤：“有事封疏以闻，勿口奏。”宦官求美女知书者数人，内之宫中，阴令诇察其事，尽得胤密谋，上不之觉也。全诲等大惧，每宴聚，流涕相诀别，日夜谋所以去胤之术。胤时领三司使，全诲等教禁军对上喧噪，诉胤减损冬衣。上不得已，解胤盐铁使。时硃全忠、李茂贞各有挟天子令诸侯之意，全忠欲上幸东都，茂贞欲上幸凤翔。胤知谋泄，事急，遗硃全忠书，称被密诏，令全忠以兵迎车驾，且言：“昨者返正，皆令公良图，而凤翔先入朝抄取其功。今不速来，必成罪人，岂惟功为他人所有，且见征讨矣！”全忠得书，秋，七月，甲寅，遽归大梁发兵。；核对说明：只据本段确认参与身份；同名与异体字回查后复用。", "status": "draft", "id": "56b9a5e6-eea8-59bb-95f0-6a4190f192f9", "subject_id": "68ed6c03-00b5-5281-8995-2d3a25982c35", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "韩全诲：求哀者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p029·原文件第68行", "note": "原文：韩全诲等涕泣求哀于上，上乃令胤：“有事封疏以闻，勿口奏。”；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "a5574db5-0060-54a7-8622-bccf6635de27", "subject_id": "6a2e451a-6214-58b3-a594-18e1a52af499", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李杰：令改奏法者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p029·原文件第68行", "note": "原文：韩全诲等涕泣求哀于上，上乃令胤：“有事封疏以闻，勿口奏。”；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "6a673162-d843-53e7-b056-7c763e29885d", "subject_id": "26a72e4e-7240-5aee-a0aa-522402dbbdfb", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "崔胤：被令封疏者。", "citation": "卷262·天复元年（901）·zztj-v262-y0901-p029·原文件第68行", "note": "原文：韩全诲等涕泣求哀于上，上乃令胤：“有事封疏以闻，勿口奏。”；核对说明：参与身份依据本段措辞，不因同场出现推定额外关系。", "status": "draft", "id": "c1866df9-fa1b-57ed-89e2-b402b1bf98a1", "subject_id": "1b8c5f28-72b1-5ebd-be84-1e1f9103975e", "source_id": "b4c91b2a-3a01-5917-9a14-432ab6a02920"}, {"subject_table": "even